import createClient from 'openapi-fetch';
import type { paths } from './schema';

// The one way the app reaches the API (docs/api-conventions.md): paths,
// parameters, bodies and responses are typed from the committed contract
// (openapi/openapi.json → schema.d.ts, regenerated by `pnpm contract`).
//
// The API shares the page's origin in every environment (the dev server and
// the production web server forward /api), so the base is the page's own
// origin, spelled out because the Request class used by the tests rejects
// relative URLs. Cookies are same-origin: the refresh cookie rides on them.
// fetch is looked up per call so tests can stub it. The auth middleware
// (bearer header, refresh on 401) is registered by src/auth/session.ts.
export const api = createClient<paths>({
  baseUrl: window.location.origin,
  credentials: 'same-origin',
  fetch: (request) => globalThis.fetch(request),
});

export type { components, operations, paths } from './schema';
